custom_qss:
/* ============================================================
   CAPSULE — abstract by shape, not color. One teal-mint hue on a
   desaturated grey-green, but every radius pushed absurd: pill
   buttons, circular tabs, fully round indicators, lozenge inputs.
   The UI becomes soft organic blobs. Unique by geometry. Every
   control is a solid high-contrast fill — no white fade.
   ============================================================ */

* { color: #dce8e2; }
QAbstractScrollArea, QFrame, QStackedWidget, QScrollArea, QTabWidget, QWidget {
    background: transparent; border: none;
}

/* window: flat dark, organic feel from the controls on top */
QMainWindow { background: #101614 !important; border: none; }
QDialog { background: #101614 !important; border: 1px solid #28352f; }

/* menubar: flat, pill selected item */
QMenuBar { background: #141b18 !important; border: none; }
QMenuBar::item { padding: 5px 14px; background: transparent !important; color: #6c8079; border-radius: 14px; }
QMenuBar::item:selected { background: #21302b !important; color: #5fd4b0; }
QMenuBar::item:disabled { color: #44544e; }

/* popup menus: heavy pill cards, pill items */
QMenu { background: #18211e !important; border: 1px solid #28352f; border-radius: 18px; padding: 8px; font-size: 12px;}
QMenu::item { padding: 7px 26px 7px 14px; background: transparent !important; color: #dce8e2; border-radius: 14px; }
QMenu::item:selected { background: #5fd4b0 !important; color: #101614; font-weight: 600; }
QMenu::item:disabled { color: #44544e; }
QMenu::separator { height: 1px; background: #28352f; margin: 6px 10px; }

/* toolbar: pill buttons */
QToolBar { background: #141b18 !important; border: none; spacing: 3px; padding: 4px; }
QToolBar::separator { background: #28352f; width: 1px; margin: 6px 5px; border-radius: 1px; }
QToolBar QToolButton, QToolButton { background: transparent !important; padding: 6px 12px; border-radius: 14px; color: #9db0a8; font-size: 12px;}
QToolBar QToolButton:hover, QToolButton:hover { background: #21302b !important; color: #5fd4b0; }
QToolBar QToolButton:checked, QToolBar QToolButton:pressed,
QToolButton:checked, QToolButton:pressed { background: #5fd4b0 !important; color: #101614; }

/* buttons: full pills */
QPushButton {
    background: #18211e !important;
    border: 1px solid #28352f; border-radius: 18px; padding: 8px 24px;
    color: #dce8e2; font-weight: 600; font-size: 12px;}
QPushButton:hover { background: #21302b !important; border: 1px solid #5fd4b0; color: #5fd4b0; }
QPushButton:pressed { background: #5fd4b0 !important; color: #101614; }
QPushButton:checked { background: #5fd4b0 !important; border: 1px solid #5fd4b0; color: #101614; }
QPushButton:default { border: 1px solid #5fd4b0; }
QPushButton:disabled { background: #141b18 !important; color: #44544e; border: 1px solid #28352f; }

/* inputs: lozenges */
QLineEdit, QSpinBox, QDoubleSpinBox, QTextEdit, QPlainTextEdit {
    background: #0b100e !important;
    border: 1px solid #28352f; border-radius: 15px; padding: 7px 14px;
    color: #5fd4b0; selection-background-color: #5fd4b0; selection-color: #101614; font-size: 12px;}
QLineEdit:focus, QSpinBox:focus, QDoubleSpinBox:focus, QTextEdit:focus, QPlainTextEdit:focus { border: 1px solid #5fd4b0; }
QLineEdit:disabled, QSpinBox:disabled, QDoubleSpinBox:disabled, QTextEdit:disabled, QPlainTextEdit:disabled { color: #44544e; }
QSpinBox::up-button, QSpinBox::down-button, QDoubleSpinBox::up-button, QDoubleSpinBox::down-button { background: transparent !important; border: none; width: 16px; }

QComboBox { background: #0b100e !important; border: 1px solid #28352f; border-radius: 15px; padding: 7px 14px; color: #dce8e2; font-size: 12px;}
QComboBox:hover { border: 1px solid #3a4a42; }
QComboBox:focus { border: 1px solid #5fd4b0; }
QComboBox::drop-down { border: none; background: transparent !important; width: 18px; }
QComboBox QAbstractItemView { background: #18211e !important; border: 1px solid #28352f; border-radius: 16px; padding: 6px; selection-background-color: #5fd4b0; selection-color: #101614; font-size: 12px;}

/* checkboxes: fully round */
QCheckBox, QRadioButton { color: #dce8e2; background: transparent !important; padding: 3px; }
QCheckBox::indicator, QRadioButton::indicator { width: 20px; height: 20px; border-radius: 11px; background: #0b100e !important; border: 1px solid #3a4a42; }
QCheckBox::indicator:hover, QRadioButton::indicator:hover { border: 1px solid #5fd4b0; }
QCheckBox::indicator:checked, QRadioButton::indicator:checked { background: #5fd4b0 !important; border: 1px solid #5fd4b0; }

/* tabs: circular pills */
QTabBar::tab { background: transparent !important; color: #6c8079; padding: 9px 20px; border: none; border-radius: 16px; margin: 0 2px; }
QTabBar::tab:hover { background: #21302b !important; color: #dce8e2; }
QTabBar::tab:selected { background: #5fd4b0 !important; color: #101614; font-weight: 700; }
QTabWidget::pane { border: none; }

/* docks: soft rounded panels */
QDockWidget { background: #18211e !important; border: 1px solid #28352f; border-radius: 14px; }
QDockWidget::title {
    background: #141b18 !important;
    border: none; border-radius: 10px; margin: 3px; padding: 7px 12px;
    color: #9db0a8; font-weight: 600;
}
QDockWidget::close-button, QDockWidget::float-button { background: transparent !important; border: none; border-radius: 9px; padding: 3px; icon-size: 13px; }
QDockWidget::close-button:hover, QDockWidget::float-button:hover { background: #21302b !important; }

QGroupBox { background: transparent !important; border: 1px solid #28352f; border-radius: 14px; margin-top: 13px; padding-top: 11px; }
QGroupBox::title { subcontrol-origin: margin; subcontrol-position: top left; padding: 0 10px; color: #5fd4b0; font-weight: 600; background: #101614; border-radius: 10px; }

QAbstractItemView { background: #0b100e !important; border: 1px solid #28352f; border-radius: 14px; outline: none; alternate-background-color: #141b18; selection-background-color: #5fd4b0; selection-color: #101614; }
QAbstractItemView::item { padding: 6px 12px; border: none; color: #dce8e2; border-radius: 10px; }
QAbstractItemView::item:hover { background: #21302b !important; color: #5fd4b0; }
QAbstractItemView::item:selected { background: #5fd4b0 !important; color: #101614; font-weight: 600; }
QTreeView::branch { background: transparent !important; }
QHeaderView::section { background: #141b18 !important; border: none; border-top-left-radius: 10px; border-top-right-radius: 10px; padding: 7px 12px; color: #9db0a8; font-weight: 600; }

QScrollBar:vertical { background: #0b100e; width: 12px; margin: 0; border: none; border-radius: 6px; }
QScrollBar::handle:vertical { background: #3a4a42; border-radius: 6px; min-height: 32px; }
QScrollBar::handle:vertical:hover { background: #5fd4b0; }
QScrollBar::add-line:vertical, QScrollBar::sub-line:vertical { height: 0; border: none; background: none; }
QScrollBar::add-page:vertical, QScrollBar::sub-page:vertical { background: none; }
QScrollBar:horizontal { background: #0b100e; height: 12px; margin: 0; border: none; border-radius: 6px; }
QScrollBar::handle:horizontal { background: #3a4a42; border-radius: 6px; min-width: 32px; }
QScrollBar::handle:horizontal:hover { background: #5fd4b0; }
QScrollBar::add-line:horizontal, QScrollBar::sub-line:horizontal { width: 0; border: none; background: none; }
QScrollBar::add-page:horizontal, QScrollBar::sub-page:horizontal { background: none; }
QScrollBar::corner { background: none; }

QSlider::groove:horizontal { background: #0b100e; border: 1px solid #28352f; height: 8px; border-radius: 4px; }
QSlider::sub-page:horizontal { background: #5fd4b0; border-radius: 4px; }
QSlider::add-page:horizontal { background: #0b100e; border-radius: 4px; }
QSlider::handle:horizontal { background: #5fd4b0; width: 18px; height: 18px; margin: -6px 0; border: 2px solid #101614; border-radius: 10px; }
QSlider::handle:horizontal:hover { background: #8ff0d0; }
QSlider::groove:vertical { background: #0b100e; border: 1px solid #28352f; width: 8px; border-radius: 4px; }
QSlider::sub-page:vertical { background: #5fd4b0; border-radius: 4px; }
QSlider::handle:vertical { background: #5fd4b0; width: 18px; height: 18px; margin: 0 -6px; border: 2px solid #101614; border-radius: 10px; }

QProgressBar { background: #0b100e; border: 1px solid #28352f; border-radius: 10px; text-align: center; color: #9db0a8; font-size: 11px; min-height: 16px; }
QProgressBar::chunk { background: #5fd4b0; border-radius: 8px; }

QStatusBar { background: #141b18 !important; border: none; color: #6c8079; font-size: 11px; }
QStatusBar::item { border: none; }
QToolTip { background: #18211e !important; border: 1px solid #5fd4b0; border-radius: 12px; padding: 6px 12px; color: #dce8e2; }
QSplitter::handle { background: #28352f; border-radius: 3px; }
QSplitter::handle:hover { background: #5fd4b0; }
QListView, QListWidget, QTreeWidget, QTableWidget { background: #0b100e !important; border: 1px solid #28352f; border-radius: 14px; outline: none; }
